#include <stdio.h>

int gcd(int a, int b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}

int main() {
    printf("%d", gcd(48, 18));
    return 0;
}

#include <stdio.h>
void bubbleSort(int** arr, int size) {
    for (int i = 0; i < size - 1; i++) {
        for (int j = 0; j < size - 1 - i; j++) {
            if ((*arr)[j] > (*arr)[j+1]) {
                int t = (*arr)[j];
                (*arr)[j] = (*arr)[j+1];
                (*arr)[j+1] = t;
            }
        }
    }
}
int main() {
    int arr[] = {5, 2, 4, 1, 3};
    int* p = arr;
    bubbleSort(&p, 5);
    printf("%d", arr[2]);
    return 0;
}

public class Main {
  static class MyException extends RuntimeException {
    MyException(String msg) { super(msg); }
  }
  static int check(int x) {
    if (x < 0) throw new MyException("negative");
    return x * 2;
  }
  public static void main(String[] args) {
    int result = 0;
    try {
      result += check(3);
      result += check(-1);
      result += check(5);
    } catch (MyException e) {
      result += 100;
    } finally {
      result += 1;
    }
    System.out.print(result);
  }
}

