int process(int arr[], int n) {
    int i = 0;
    int result = 0;
    while (i < n) {
        if (arr[i] % 2 == 0) {
            result += arr[i] * 2;
        } else {
            result -= arr[i];
        }
        i++;
    }
    return result;
}

